"use strict";(self.webpackChunklightweight_charts_website=self.webpackChunklightweight_charts_website||[]).push([["15085"],{60251:function(n,e,t){t.r(e),t.d(e,{default:function(){return a}});let a="// remove-start\n// Lightweight Charts\u2122 Example: Realtime updates\n// https://tradingview.github.io/lightweight-charts/examples/data/realtime-updates\n\n// remove-end\n\n// hide-start\nlet randomFactor = 25 + Math.random() * 25;\nconst samplePoint = i =>\n	i *\n		(0.5 +\n			Math.sin(i / 1) * 0.2 +\n			Math.sin(i / 2) * 0.4 +\n			Math.sin(i / randomFactor) * 0.8 +\n			Math.sin(i / 50) * 0.5) +\n	200 +\n	i * 2;\n\nfunction generateData(\n	numberOfCandles = 500,\n	updatesPerCandle = 5,\n	startAt = 100\n) {\n	const createCandle = (val, time) => ({\n		time,\n		open: val,\n		high: val,\n		low: val,\n		close: val,\n	});\n\n	const updateCandle = (candle, val) => ({\n		time: candle.time,\n		close: val,\n		open: candle.open,\n		low: Math.min(candle.low, val),\n		high: Math.max(candle.high, val),\n	});\n\n	randomFactor = 25 + Math.random() * 25;\n	const date = new Date(Date.UTC(2018, 0, 1, 12, 0, 0, 0));\n	const numberOfPoints = numberOfCandles * updatesPerCandle;\n	const initialData = [];\n	const realtimeUpdates = [];\n	let lastCandle;\n	let previousValue = samplePoint(-1);\n	for (let i = 0; i < numberOfPoints; ++i) {\n		if (i % updatesPerCandle === 0) {\n			date.setUTCDate(date.getUTCDate() + 1);\n		}\n		const time = date.getTime() / 1000;\n		let value = samplePoint(i);\n		const diff = (value - previousValue) * Math.random();\n		value = previousValue + diff;\n		previousValue = value;\n		if (i % updatesPerCandle === 0) {\n			const candle = createCandle(value, time);\n			lastCandle = candle;\n			if (i >= startAt) {\n				realtimeUpdates.push(candle);\n			}\n		} else {\n			const newCandle = updateCandle(lastCandle, value);\n			lastCandle = newCandle;\n			if (i >= startAt) {\n				realtimeUpdates.push(newCandle);\n			} else if ((i + 1) % updatesPerCandle === 0) {\n				initialData.push(newCandle);\n			}\n		}\n	}\n\n	return {\n		initialData,\n		realtimeUpdates,\n	};\n}\n\nconst chartOptions = {\n	layout: {\n		textColor: CHART_TEXT_COLOR,\n		background: { type: 'solid', color: CHART_BACKGROUND_COLOR },\n	},\n	grid: {\n		vertLines: { color: CHART_GRID_COLOR },\n		horzLines: { color: CHART_GRID_COLOR },\n	},\n	// Fill the element the chart is created in, whatever its size.\n	autoSize: true,\n};\n// hide-end\nconst container = document.getElementById('container');\n// The chart takes the space above the buttons, which are added further down.\ncontainer.style.display = 'flex';\ncontainer.style.flexDirection = 'column';\nconst chartElement = document.createElement('div');\nchartElement.style.flex = '1';\nchartElement.style.minHeight = '0';\ncontainer.appendChild(chartElement);\n// remove-line\n/** @type {import('lightweight-charts').IChartApi} */\nconst chart = createChart(chartElement, chartOptions);\n\nconst series = chart.addSeries(CandlestickSeries, {\n	upColor: BAR_UP_COLOR,\n	downColor: BAR_DOWN_COLOR,\n	borderVisible: false,\n	wickUpColor: BAR_UP_COLOR,\n	wickDownColor: BAR_DOWN_COLOR,\n});\n\nconst data = generateData(2500, 20, 1000);\n\nseries.setData(data.initialData);\nchart.timeScale().fitContent();\nchart.timeScale().scrollToPosition(5);\n\n// simulate real-time data\nfunction* getNextRealtimeUpdate(realtimeData) {\n	for (const dataPoint of realtimeData) {\n		yield dataPoint;\n	}\n	return null;\n}\nconst streamingDataProvider = getNextRealtimeUpdate(data.realtimeUpdates);\n\nconst intervalID = setInterval(() => {\n	const update = streamingDataProvider.next();\n	if (update.done) {\n		clearInterval(intervalID);\n		return;\n	}\n	series.update(update.value);\n}, 100);\n\n// hide-start\nconst styles = `\n    .buttons-container {\n        display: flex;\n        flex-direction: row;\n        gap: 8px;\n        padding: 8px;\n        background-color: ${CHART_BACKGROUND_COLOR};\n    }\n    .buttons-container button {\n        all: initial;\n        font-family: -apple-system, BlinkMacSystemFont, 'Trebuchet MS', Roboto, Ubuntu,\n            sans-serif;\n        font-size: 16px;\n        font-style: normal;\n        font-weight: 510;\n        line-height: 24px; /* 150% */\n        letter-spacing: -0.32px;\n        padding: 8px 24px;\n        color: ${BUTTON_TEXT_COLOR};\n        background-color: ${BUTTON_COLOR};\n        border-radius: 8px;\n        cursor: pointer;\n    }\n\n    .buttons-container button:hover {\n        background-color: ${BUTTON_HOVER_COLOR};\n    }\n\n    .buttons-container button:active {\n        background-color: ${BUTTON_ACTIVE_COLOR};\n    }\n`;\n\nconst stylesElement = document.createElement('style');\nstylesElement.innerHTML = styles;\ncontainer.appendChild(stylesElement);\n\nconst buttonsContainer = document.createElement('div');\nbuttonsContainer.classList.add('buttons-container');\n// hide-end\nconst button = document.createElement('button');\nbutton.innerText = 'Go to realtime';\nbutton.addEventListener('click', () => chart.timeScale().scrollToRealTime());\nbuttonsContainer.appendChild(button);\n\ncontainer.appendChild(buttonsContainer);\n"}}]);